using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
[InitializeOnLoad]
public static class F2RVerification
{
 static F2RVerification(){EditorApplication.playModeStateChanged+=s=>{if(!SessionState.GetBool("F2R.Run",false))return;if(s==PlayModeStateChange.EnteredPlayMode)new GameObject("F2R display verification").AddComponent<F2RRunner>();if(s==PlayModeStateChange.EnteredEditMode){SessionState.SetBool("F2R.Run",false);EditorApplication.Exit(SessionState.GetInt("F2R.Exit",1));}};}
 public static void Run(){if(File.Exists(Nightly.Path("F2R-feedback")))throw new IOException("Preserve evidence");SessionState.SetBool("F2R.Run",true);EditorSceneManager.OpenScene("Assets/Scenes/Test/CombatTest.unity");EditorApplication.delayCall+=()=>EditorApplication.isPlaying=true;}
}
public sealed class F2RRunner:MonoBehaviour
{
 readonly List<string> lines=new(),errors=new();Keyboard kb;
 void Check(bool ok,string message){if(!ok)throw new Exception(message);lines.Add("PASS: "+message);}
 void Log(string m,string s,LogType t){if(t is LogType.Error or LogType.Exception or LogType.Assert)errors.Add(m+s);}
 IEnumerator Start(){Application.logMessageReceived+=Log;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;QualitySettings.vSyncCount=0;kb=InputSystem.AddDevice<Keyboard>();var stack=new Stack<IEnumerator>();stack.Push(Tests());bool fail=false;while(stack.Count>0&&!fail){object next=null;try{if(!stack.Peek().MoveNext()){stack.Pop();continue;}next=stack.Peek().Current;}catch(Exception e){fail=true;lines.Add(e.ToString());}if(next is IEnumerator child)stack.Push(child);else if(!fail)yield return next;}Application.logMessageReceived-=Log;InputSystem.RemoveDevice(kb);fail|=errors.Count>0;lines.AddRange(errors);lines.Insert(0,fail?"FAIL F2R":"PASS F2R");lines.Add("Error/Exception/Assert="+errors.Count);File.WriteAllLines(Nightly.Path("F2R-feedback"),lines);SessionState.SetInt("F2R.Exit",fail?1:0);EditorApplication.isPlaying=false;}
 IEnumerator Keys(params Key[] keys){InputSystem.QueueStateEvent(kb,new KeyboardState(keys));yield return null;}
 void Place(Vector2 p){var player=RoomSession.Instance.Player;player.ClearTransientInput();player.transform.position=p;var body=player.GetComponent<Rigidbody2D>();body.position=p;body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
 IEnumerator Tests(){yield return new WaitForSeconds(.3f);var player=RoomSession.Instance.Player;var attack=player.GetComponent<PlayerAttack>();var fx=player.GetComponent<AttackFeedback>();var health=player.GetComponent<PlayerHealth>();var dummy=FindFirstObjectByType<DummyTarget>();var e2=FindFirstObjectByType<EnemyCharger>();e2.enabled=false;foreach(var e in FindObjectsByType<EnemyTurret>(FindObjectsSortMode.None))e.enabled=false;var e1=FindFirstObjectByType<EnemyPatrol>();e1.enabled=false;var hit=dummy.GetComponent<HitFeedback>();Check(fx!=null&&hit!=null,"player/dummy recovered display binding");var center=typeof(PlayerAttack).GetMethod("Center",BindingFlags.NonPublic|BindingFlags.Instance);
 foreach(int fps in new[]{30,60,120}){Application.targetFrameRate=fps;yield return new WaitForSeconds(.2f);foreach(int dir in new[]{1,-1}){health.RestoreMax();Place(new Vector2(6,1.81f));yield return Keys(dir>0?Key.RightArrow:Key.LeftArrow);yield return new WaitForFixedUpdate();yield return Keys();yield return new WaitForSeconds(.5f);dummy.transform.position=new Vector3(30,8,0);int before=hit.Calls;yield return Keys(Key.X);Check(attack.Attacking&&!fx.slash.gameObject.activeSelf,$"{fps} {dir} startup inactive");yield return Keys();double end=Time.timeAsDouble+1;while(!fx.slash.gameObject.activeSelf&&Time.timeAsDouble<end)yield return null;Check(fx.slash.gameObject.activeSelf,"active slash "+fps);Check(Vector2.Distance(fx.slash.bounds.center,(Vector2)center.Invoke(attack,null))<=.01f&&Vector2.Distance(fx.slash.bounds.size,new Vector2(attack.tuning.attackRange,attack.tuning.attackHeight))<=.01f,"center/size <=.01u "+fps+" "+dir);yield return new WaitForSeconds(.2f);Check(!fx.slash.gameObject.activeSelf&&hit.Calls==before,"end inactive/miss0");yield return new WaitForSeconds(.4f);dummy.transform.position=(Vector2)center.Invoke(attack,null);Physics2D.SyncTransforms();before=hit.Calls;int hp=dummy.HP;yield return Keys(Key.X);yield return Keys();end=Time.timeAsDouble+1;while(hit.Calls==before&&Time.timeAsDouble<end)yield return null;Check(hit.Calls==before+1&&dummy.HP==hp-1&&hit.VisibleHP==dummy.HP&&hit.overlay.gameObject.activeSelf,"accepted hit1/HP/overlay");int white=0;foreach(var sr in dummy.GetComponentsInChildren<SpriteRenderer>())if(sr.name.StartsWith("HP pip")&&sr.color==Color.white)white++;Check(white==dummy.HP,"white pip count = remaining HP");while(hit.overlay.gameObject.activeSelf)yield return null;double duration=hit.FlashEnded-hit.FlashStarted;Check(Math.Abs(duration-.10)<=1.0/fps+.006,"flash duration="+duration);yield return new WaitForSeconds(.5f);}}
 Application.targetFrameRate=60;dummy.transform.position=new Vector3(30,8,0);health.RestoreMax();Place(new Vector2(8,1.81f));e2=Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/E2.prefab"),new Vector3(10,1.51f,0),Quaternion.identity).GetComponent<EnemyCharger>();var eb=e2.GetComponent<Rigidbody2D>();e2.transform.position=new Vector3(10,1.51f,0);eb.position=e2.transform.position;eb.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();e2.enabled=true;double deadline=Time.timeAsDouble+1;while(e2.State!=EnemyCharger.Phase.Warning&&Time.timeAsDouble<deadline)yield return null;Check(e2.State==EnemyCharger.Phase.Warning,"E2 warning setup");var eh=e2.GetComponent<HitFeedback>();int calls=eh.Calls;e2.ReceiveHit(1,player.transform.position);Check(eh.Calls==calls+1&&eh.overlay.gameObject.activeSelf&&e2.State==EnemyCharger.Phase.Warning,"E2 warning hit overlay independently active");e2.enabled=false;
 e1=FindFirstObjectByType<EnemyPatrol>();if(e1==null)e1=Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/E1.prefab"),new Vector3(20,1.5f,0),Quaternion.identity).GetComponent<EnemyPatrol>();e1.enabled=false;int pops=HitFeedback.PopsCreated;e1.ReceiveHit(e1.HP,player.transform.position);Check(HitFeedback.PopsCreated==pops+1,"E1 death pop1");yield return new WaitForSeconds(.3f);Check(FindObjectsByType<DeathPop>(FindObjectsSortMode.None).Length==0,"death pop expires");attack.Cancel();Check(!fx.slash.gameObject.activeSelf,"Cancel immediate hide");lines.Add("No pixel sampling; human display acceptance pending.");}
}
